  using Entry=std::pair<bool,long long>;int ready=0;std::vector<long long> dp(n+1);cp::Larsch<Entry> online(n,[&](int i,int j)->Entry{if(j>i)return {true,0};CHECK(j<=ready);return {false,dp[j]+cost(j,i+1)};});for(int repetition=0;repetition<2;++repetition){ready=0;for(int v=1;v<=n;++v){int p=online.next_argmin();dp[v]=dp[p]+cost(p,v);ready=v;CHECK(dp[v]==expected[v]);}bool rejected=false;try{online.next_argmin();}catch(const std::out_of_range&){rejected=true;}CHECK(rejected);online.reset();}
